# jax.experimental.sparse. Expected values are from jax 0.12.0.1 (generated, float32).

spx <- function(got, w, tol = 2e-6) {
  testthat::expect_identical(dtype(got), w[[1L]])
  testthat::expect_identical(as.integer(dim(got)), as.integer(w[[2L]]))
  gv <- as.array(got)
  if (length(dim(gv)) > 1L) gv <- aperm(gv)
  gv <- as.vector(gv)
  if (is.logical(w[[3L]])) return(testthat::expect_identical(as.logical(gv), w[[3L]]))
  testthat::expect_true(all(abs(gv - w[[3L]]) <= tol * (1 + abs(w[[3L]]))), info = paste(format(gv), collapse = ' '))
}

M <- as_jax(aperm(array(c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2), c(4L, 3L)), c(2, 1)), "float32")
B <- as_jax(aperm(array(c(0, 0x1.0000000000000p+0, 0, 0, 0x1.0000000000000p+1, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0x1.0000000000000p+2, 0, 0x1.4000000000000p+2, 0, 0, 0, 0, 0x1.8000000000000p+2, 0x1.c000000000000p+2, 0, 0, 0), c(4L, 3L, 2L)), c(3, 2, 1)), "float32")
D <- as_jax(aperm(array(c(0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, 0, 0), c(2L, 2L, 3L)), c(3, 2, 1)), "float32")
v4 <- as_jax(array(c(0x1.0000000000000p+0, -0x1.0000000000000p+1, 0x1.0000000000000p-1, 0x1.8000000000000p+1)), "float32")
W <- as_jax(aperm(array(c(0x1.0000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.0000000000000p+0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+0, 0x1.0000000000000p+0), c(2L, 4L)), c(2, 1)), "float32")
v3 <- as_jax(array(c(0x1.0000000000000p+1, -0x1.0000000000000p+0, 0x1.0000000000000p-1)), "float32")

test_that("BCOO conversion match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_BCOO$fromdense(M)$data, list("float32", c(5L), c(0x1.8000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_BCOO$fromdense(M)$indices, list("int32", c(5L, 2L), c(0, 0x1.0000000000000p+0, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.0000000000000p+1, 0x1.0000000000000p+1, 0x1.8000000000000p+1)))
  spx(experimental_sparse_BCOO$fromdense(M)$todense(), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_BCOO$fromdense(B, n_batch = 1L)$data, list("float32", c(2L, 4L), c(0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.4000000000000p+2, 0x1.8000000000000p+2, 0x1.c000000000000p+2)))
  spx(experimental_sparse_BCOO$fromdense(B, n_batch = 1L)$indices, list("int32", c(2L, 4L, 2L), c(0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+0, 0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.0000000000000p+2, 0, 0, 0, 0x1.0000000000000p+1, 0x1.0000000000000p+0, 0x1.8000000000000p+1, 0x1.0000000000000p+1, 0)))
  spx(experimental_sparse_BCOO$fromdense(B, n_batch = 1L)$todense(), list("float32", c(2L, 3L, 4L), c(0, 0x1.0000000000000p+0, 0, 0, 0x1.0000000000000p+1, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0x1.0000000000000p+2, 0, 0x1.4000000000000p+2, 0, 0, 0, 0, 0x1.8000000000000p+2, 0x1.c000000000000p+2, 0, 0, 0)))
  spx(experimental_sparse_BCOO$fromdense(D, n_dense = 1L)$data, list("float32", c(2L, 2L), c(0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0)))
  spx(experimental_sparse_BCOO$fromdense(D, n_dense = 1L)$indices, list("int32", c(2L, 2L), c(0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0)))
  spx(experimental_sparse_BCOO$fromdense(D, n_dense = 1L)$todense(), list("float32", c(3L, 2L, 2L), c(0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, 0, 0)))
  spx(experimental_sparse_BCOO$fromdense(M, nse = 7L)$todense(), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_BCOO$fromdense(M, nse = 7L)$indices, list("int32", c(7L, 2L), c(0, 0x1.0000000000000p+0, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.0000000000000p+1, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.0000000000000p+2, 0x1.8000000000000p+1, 0x1.0000000000000p+2)))
  spx(experimental_sparse_todense(experimental_sparse_BCOO$fromdense(M)), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_extract(experimental_sparse_BCOO$fromdense(M), M * 2)$data, list("float32", c(5L), c(0x1.8000000000000p+1, 0x1.0000000000000p+2, 0x1.8000000000000p+2, -0x1.0000000000000p+1, 0x1.0000000000000p+3)))
})

test_that("BCOO products match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_BCOO$fromdense(M) %*% v4, list("float32", c(3L), c(0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.7000000000000p+3)))
  spx(experimental_sparse_BCOO$fromdense(M) %*% W, list("float32", c(3L, 2L), c(0x1.4000000000000p+2, 0x1.c000000000000p+1, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.4000000000000p+2)))
  spx(v3 %*% experimental_sparse_BCOO$fromdense(M), list("float32", c(4L), c(-0x1.8000000000000p+1, 0x1.8000000000000p+1, -0x1.0000000000000p-1, 0x1.8000000000000p+2)))
  spx(experimental_sparse_bcoo_dot_general(experimental_sparse_BCOO$fromdense(B, n_batch = 1L), W, list(list(2L, 0L), list(integer(0), integer(0)))), list("float32", c(2L, 3L, 2L), c(0x1.0000000000000p+1, 0x1.0000000000000p+0, 0x1.4000000000000p+2, 0x1.8000000000000p+1, 0, 0, 0x1.0000000000000p+2, -0x1.4000000000000p+2, 0x1.8000000000000p+2, 0x1.8000000000000p+2, 0x1.c000000000000p+2, 0)))
  spx(experimental_sparse_bcoo_dot_general(experimental_sparse_BCOO$fromdense(M), experimental_sparse_BCOO$fromdense(t(as.array(M))), list(list(1L, 0L), list(integer(0), integer(0))))$todense(), list("float32", c(3L, 3L), c(0x1.9000000000000p+2, 0, 0x1.0000000000000p+3, 0, 0x1.2000000000000p+3, 0, 0x1.0000000000000p+3, 0, 0x1.1000000000000p+4)))
  spx(experimental_sparse_bcoo_dot_general_sampled(W, t(as.array(W)), experimental_sparse_BCOO$fromdense(diag(4))$indices, list(list(1L, 0L), list(integer(0), integer(0)))), list("float32", c(4L), c(0x1.0000000000000p+0, 0x1.4000000000000p+2, 0x1.0000000000000p+0, 0x1.0000000000000p+1)))
  spx(experimental_sparse_bcoo_multiply_dense(experimental_sparse_BCOO$fromdense(M), v4), list("float32", c(5L), c(-0x1.8000000000000p+1, 0x1.8000000000000p+2, 0x1.8000000000000p+1, -0x1.0000000000000p-1, 0x1.8000000000000p+3)))
  spx(experimental_sparse_bcoo_multiply_sparse(experimental_sparse_BCOO$fromdense(M), experimental_sparse_BCOO$fromdense(M))$todense(), list("float32", c(3L, 4L), c(0, 0x1.2000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.2000000000000p+3, 0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+4)))
})

test_that("BCOO structural functions match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_BCOO$fromdense(M)$T$todense(), list("float32", c(4L, 3L), c(0, 0x1.8000000000000p+1, 0, 0x1.8000000000000p+0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+1, 0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_transpose(experimental_sparse_BCOO$fromdense(B, n_batch = 1L), c(0L, 2L, 1L))$todense(), list("float32", c(2L, 4L, 3L), c(0, 0x1.0000000000000p+1, 0, 0x1.0000000000000p+0, 0, 0, 0, 0, 0, 0, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0, 0x1.c000000000000p+2, 0, 0, 0, 0x1.4000000000000p+2, 0, 0, 0, 0x1.8000000000000p+2, 0)))
  spx(experimental_sparse_bcoo_reshape(experimental_sparse_BCOO$fromdense(M), c(2L, 6L))$todense(), list("float32", c(2L, 6L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_rev(experimental_sparse_BCOO$fromdense(M), c(0L, 1L))$todense(), list("float32", c(3L, 4L), c(0x1.0000000000000p+2, -0x1.0000000000000p+0, 0, 0, 0, 0, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+1, 0, 0x1.8000000000000p+0, 0)))
  spx(experimental_sparse_bcoo_slice(experimental_sparse_BCOO$fromdense(M), c(1L, 1L), c(3L, 4L))$todense(), list("float32", c(2L, 3L), c(0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_slice(experimental_sparse_BCOO$fromdense(M), c(0L, 0L), c(3L, 4L), c(2L, 2L))$todense(), list("float32", c(2L, 2L), c(0, 0, 0, -0x1.0000000000000p+0)))
  spx(experimental_sparse_bcoo_dynamic_slice(experimental_sparse_BCOO$fromdense(M), list(1L, 2L), c(2L, 2L))$todense(), list("float32", c(2L, 2L), c(0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_squeeze(experimental_sparse_BCOO$fromdense(array(c(0, 1, 0, 2), c(1L, 4L))), 0L)$todense(), list("float32", c(4L), c(0, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+1)))
  spx(experimental_sparse_bcoo_broadcast_in_dim(experimental_sparse_BCOO$fromdense(M), c(2L, 3L, 4L), c(1L, 2L))$todense(), list("float32", c(2L, 3L, 4L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2, 0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_concatenate(list(experimental_sparse_BCOO$fromdense(M), experimental_sparse_BCOO$fromdense(M)), 1L)$todense(), list("float32", c(3L, 8L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_reduce_sum(experimental_sparse_BCOO$fromdense(M), 1L)$todense(), list("float32", c(3L), c(0x1.c000000000000p+1, 0x1.8000000000000p+1, 0x1.8000000000000p+1)))
  spx(experimental_sparse_bcoo_reduce_sum(experimental_sparse_BCOO$fromdense(B, n_batch = 1L), c(0L, 2L))$todense(), list("float32", c(3L), c(0x1.4000000000000p+3, 0x1.6000000000000p+3, 0x1.c000000000000p+2)))
  spx(experimental_sparse_bcoo_update_layout(experimental_sparse_BCOO$fromdense(B, n_batch = 1L), n_batch = 0L)$todense(), list("float32", c(2L, 3L, 4L), c(0, 0x1.0000000000000p+0, 0, 0, 0x1.0000000000000p+1, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0x1.0000000000000p+2, 0, 0x1.4000000000000p+2, 0, 0, 0, 0, 0x1.8000000000000p+2, 0x1.c000000000000p+2, 0, 0, 0)))
  spx(experimental_sparse_bcoo_update_layout(experimental_sparse_BCOO$fromdense(B), n_batch = 1L, on_inefficient = NULL)$todense(), list("float32", c(2L, 3L, 4L), c(0, 0x1.0000000000000p+0, 0, 0, 0x1.0000000000000p+1, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0x1.0000000000000p+2, 0, 0x1.4000000000000p+2, 0, 0, 0, 0, 0x1.8000000000000p+2, 0x1.c000000000000p+2, 0, 0, 0)))
  spx(experimental_sparse_bcoo_update_layout(experimental_sparse_BCOO$fromdense(M), n_dense = 1L, on_inefficient = NULL)$todense(), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, -0x1.0000000000000p+0, 0x1.0000000000000p+2)))
  spx(experimental_sparse_bcoo_update_layout(experimental_sparse_BCOO$fromdense(D, n_dense = 1L), n_dense = 0L)$todense(), list("float32", c(3L, 2L, 2L), c(0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, 0, 0)))
  spx(experimental_sparse_bcoo_sort_indices(experimental_sparse_BCOO$fromdense(M)$T)$indices, list("int32", c(5L, 2L), c(0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+1, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+1)))
})

DUP <- experimental_sparse_BCOO(list(as_jax(array(c(0x1.0000000000000p+0, 0x1.0000000000000p+1, 0x1.8000000000000p+1, 0x1.0000000000000p+2)), "float32"), as_jax(aperm(array(c(0, 0x1.0000000000000p+0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+0), c(2L, 4L)), c(2, 1)), "int32")), shape = c(3L, 2L))

test_that("BCOO duplicates match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_bcoo_sum_duplicates(DUP)$data, list("float32", c(3L), c(0x1.8000000000000p+1, 0x1.0000000000000p+2, 0x1.8000000000000p+1)))
  spx(experimental_sparse_bcoo_sum_duplicates(DUP)$indices, list("int32", c(3L, 2L), c(0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0)))
  spx(experimental_sparse_bcoo_sum_duplicates(DUP, nse = 4L)$indices, list("int32", c(4L, 2L), c(0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0x1.0000000000000p+0, 0x1.0000000000000p+1, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+1)))
  spx(DUP$todense(), list("float32", c(3L, 2L), c(0, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.8000000000000p+1, 0)))
  spx(DUP$sum_duplicates()$data, list("float32", c(3L), c(0x1.8000000000000p+1, 0x1.0000000000000p+2, 0x1.8000000000000p+1)))
  spx(experimental_sparse_bcoo_extract(DUP, matrix(1:6, 3, 2, byrow = TRUE) + 0)$data, list("float32", c(4L), c(0x1.0000000000000p+1, 0, 0x1.4000000000000p+2, 0x1.0000000000000p+2)))
})

test_that("BCOO autodiff match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_grad(function(m) jnp_sum(jnp_sin(m %*% v4)))(experimental_sparse_BCOO$fromdense(M))$data, list("float32", c(5L), c(0x1.fae04c0000000p+0, -0x1.7c28380000000p+1, -0x1.fae04c0000000p-1, 0x1.eee7720000000p-3, 0x1.732d960000000p+0)))
  spx(grad(function(v) jnp_sum(jnp_sin(experimental_sparse_BCOO$fromdense(M) %*% v)))(v4), list("float32", c(4L), c(-0x1.7c28380000000p+1, -0x1.7c28380000000p+0, -0x1.eee7720000000p-2, -0x1.7f1b400000000p-5)))
  spx(grad(function(d) jnp_sum(experimental_sparse_BCOO(list(d, experimental_sparse_BCOO$fromdense(M)$indices), shape = c(3L, 4L)) %*% W))(experimental_sparse_BCOO$fromdense(M)$data), list("float32", c(5L), c(0x1.8000000000000p+1, 0x1.0000000000000p+1, 0x1.0000000000000p+0, -0x1.0000000000000p+0, 0x1.0000000000000p+1)))
  spx(grad(function(x) jnp_sum(experimental_sparse_bcoo_todense(experimental_sparse_BCOO$fromdense(x, nse = 5L))^2))(M), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.8000000000000p+2, 0, 0, 0, 0, 0, -0x1.0000000000000p+1, 0x1.0000000000000p+3)))
  spx(experimental_sparse_jacfwd(function(m) m %*% v4)(experimental_sparse_BCOO$fromdense(M))$data, list("float32", c(3L, 5L), c(-0x1.0000000000000p+1, 0x1.8000000000000p+1, 0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0, 0, 0x1.0000000000000p-1, 0x1.8000000000000p+1)))
  spx(experimental_sparse_value_and_grad(function(m) jnp_sum(m %*% v4))(experimental_sparse_BCOO$fromdense(M))[[1L]], list("float32", integer(0), c(0x1.1800000000000p+4)))
  spx(jit(function(d, i, v) experimental_sparse_BCOO(list(d, i), shape = c(3L, 4L)) %*% v)(experimental_sparse_BCOO$fromdense(M)$data, experimental_sparse_BCOO$fromdense(M)$indices, v4), list("float32", c(3L), c(0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.7000000000000p+3)))
  spx(vmap(function(m) experimental_sparse_bcoo_todense(experimental_sparse_BCOO$fromdense(m, nse = 3L)))(B), list("float32", c(2L, 3L, 4L), c(0, 0x1.0000000000000p+0, 0, 0, 0x1.0000000000000p+1, 0, 0, 0x1.8000000000000p+1, 0, 0, 0, 0, 0x1.0000000000000p+2, 0, 0x1.4000000000000p+2, 0, 0, 0, 0, 0x1.8000000000000p+2, 0, 0, 0, 0)))
  spx(vmap(function(v) experimental_sparse_BCOO$fromdense(M) %*% v)(rbind(as.array(v4), as.array(v4) * 2)), list("float32", c(2L, 3L), c(0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.7000000000000p+3, 0x1.8000000000000p+2, 0x1.8000000000000p+2, 0x1.7000000000000p+4)))
})

test_that("sparsify match JAX", {
  skip_if_no_backend()
  spx(experimental_sparse_sparsify(function(m, v) jnp_sin(m) %*% v)(experimental_sparse_BCOO$fromdense(M), v4), list("float32", c(3L), c(0x1.773ef40000000p-1, 0x1.2103860000000p-3, -0x1.5877600000000p+1)))
  spx((experimental_sparse_BCOO$fromdense(M) + experimental_sparse_BCOO$fromdense(M))$todense(), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.8000000000000p+2, 0, 0, 0, 0, 0, -0x1.0000000000000p+1, 0x1.0000000000000p+3)))
  spx((experimental_sparse_BCOO$fromdense(M) * 2)$todense(), list("float32", c(3L, 4L), c(0, 0x1.8000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.8000000000000p+2, 0, 0, 0, 0, 0, -0x1.0000000000000p+1, 0x1.0000000000000p+3)))
  spx((experimental_sparse_BCOO$fromdense(M) * M)$todense(), list("float32", c(3L, 4L), c(0, 0x1.2000000000000p+1, 0, 0x1.0000000000000p+2, 0x1.2000000000000p+3, 0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0x1.0000000000000p+4)))
  spx((-experimental_sparse_BCOO$fromdense(M))$todense(), list("float32", c(3L, 4L), c(0, -0x1.8000000000000p+0, 0, -0x1.0000000000000p+1, -0x1.8000000000000p+1, 0, 0, 0, 0, 0, 0x1.0000000000000p+0, -0x1.0000000000000p+2)))
