  skip_if_no_backend()
  spx(experimental_sparse_eye(4L, 3L, k = 1L)$todense(), list("float32", c(4L, 3L), c(0, 0x1.0000000000000p+0, 0, 0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0, 0, 0)))
  spx(experimental_sparse_eye(3L, k = -1L, sparse_format = 'csr')$todense(), list("float32", c(3L, 3L), c(0, 0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0x1.0000000000000p+0, 0)))
  spx(experimental_sparse_eye(3L, 4L, sparse_format = 'coo')$todense(), list("float32", c(3L, 4L), c(0x1.0000000000000p+0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0)))
  spx(experimental_sparse_eye(3L, 4L, k = 2L, sparse_format = 'csc')$todense(), list("float32", c(3L, 4L), c(0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0, 0x1.0000000000000p+0, 0, 0, 0, 0)))
