test_that("sparse misc API follows JAX", {
  skip_if_no_backend()
  m <- experimental_sparse_BCOO$fromdense(M)
  expect_identical(m$nse, 5L)
  expect_identical(m$n_sparse, 2L)
  expect_identical(m$shape, c(3L, 4L))
  expect_identical(experimental_sparse_BCOO$fromdense(B, n_batch = 1L)$n_batch, 1L)
  expect_identical(length(tree_leaves(m)), 2L)
  expect_true(inherits(m, 'jax_sparse'))
  expect_output(print(m), 'BCOO\\(float32\\[3, 4\\], nse=5\\)')
  rb <- experimental_sparse_random_bcoo(random_key(0L), c(4L, 5L), nse = 6L)
  expect_identical(rb$nse, 6L)
  expect_identical(rb$shape, c(4L, 5L))
  spx(rb$indices, list("int32", c(6L, 2L), c(0, 0, 0, 0x1.8000000000000p+1, 0x1.0000000000000p+0, 0x1.0000000000000p+2, 0x1.0000000000000p+0, 0, 0x1.8000000000000p+1, 0x1.8000000000000p+1, 0x1.0000000000000p+1, 0x1.0000000000000p+2)))
  spx(rb$data, list("float32", c(6L), c(0x1.af43cc0000000p-1, 0x1.7582f00000000p-3, 0x1.d142c00000000p-3, 0x1.ee7e000000000p-4, 0x1.88d5800000000p-3, 0x1.71abf40000000p-1)))
  expect_error(experimental_sparse_bcoo_update_layout(experimental_sparse_BCOO$fromdense(B), n_batch = 1L), class = experimental_sparse_SparseEfficiencyError)
  expect_error(experimental_sparse_sparsify(function(m) jnp_cos(m))(m), class = 'jax_not_implemented_error')
  expect_error(m / m, class = 'jax_not_implemented_error')
  expect_error(experimental_sparse_JAXSparse(), class = 'jax_type_error')
  expect_error(jit(function(d) experimental_sparse_bcoo_sum_duplicates(experimental_sparse_BCOO(list(d, DUP$indices), shape = c(3L, 2L)))$data)(DUP$data), class = 'jax_value_error')
  expect_identical(experimental_sparse_bcoo_todense_p$name, 'bcoo_todense')
})
